    /// <summary>
    /// `GetAllActiveStaticCards` 的第一层判据（`cardSet`）。
    ///
    /// ⚠️ 常见误读：数值 15..20 **不是** `includeNotAttainable` 门控的。
    /// 反编译里只有 2..7 走 `L_08CC`（那个 `if (!includeNotAttainable) 跳过` 的分支），
    /// 1 / 8 / 9 / 10 / 12 / 13 / 15 / 16 / 17 / 18 / 19 / 20 全部直接落到 `L_01F0`（保留）。
    /// 不在 SwitchEnum 链上的数值（0 / 11 / 14 / 22+）落到 `L_088C`，**无条件跳过**。
    /// </summary>
    public static bool IsSetInPool(string? cardSet, bool includeNotAttainable) =>
        CardSetIdOf(cardSet) switch
        {
            1 or 8 or 9 or 10 or 12 or 13
                or 15 or 16 or 17 or 18 or 19 or 20 => true,
            21 => OceaniaStormActive,
            2 or 3 or 4 or 5 or 6 or 7 => includeNotAttainable,
            _ => false,
        };

